// Horloge : la petite aiguille noire pour les heures, la grande bleue pour les minutes.
function clockSvg(h, m) {
  const pt = (deg, len) => { const r = (deg - 90) * Math.PI / 180; return [(50 + Math.cos(r) * len).toFixed(1), (50 + Math.sin(r) * len).toFixed(1)]; };
  const hand = (deg, len, w, col) => { const [x, y] = pt(deg, len); return `<line x1="50" y1="50" x2="${x}" y2="${y}" stroke="${col}" stroke-width="${w}" stroke-linecap="round"/>`; };
  let nums = '';
  for (let i = 1; i <= 12; i++) { const [x, y] = pt(i * 30, 34); nums += `<text x="${x}" y="${(+y + 4).toFixed(1)}" text-anchor="middle" font-size="11" font-family="Lilita One, sans-serif" fill="#1d2b22">${i}</text>`; }
  return `<svg viewBox="0 0 100 100" class="clock" aria-hidden="true"><circle cx="50" cy="50" r="46" fill="#fff" stroke="#1d2b22" stroke-width="4"/>${nums}${hand(m * 6, 36, 3, '#2f7fe0')}${hand((h % 12 + m / 60) * 30, 23, 5.5, '#1d2b22')}<circle cx="50" cy="50" r="4" fill="#1d2b22"/></svg>`;
}
